import{_ as n,o as a,c as e,a2 as p}from"./chunks/framework.DHDlZsL2.js";const m=JSON.parse('{"title":"05 路径规划与自主决策","description":"","frontmatter":{},"headers":[],"relativePath":"05_路径规划与自主决策.md","filePath":"05_路径规划与自主决策.md"}'),l={name:"05_路径规划与自主决策.md"};function r(i,s,t,c,o,b){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_05-路径规划与自主决策" tabindex="-1">05 路径规划与自主决策 <a class="header-anchor" href="#_05-路径规划与自主决策" aria-label="Permalink to &quot;05 路径规划与自主决策&quot;">​</a></h1><blockquote><p>本文档属于 <a href="/drone/drone/">全栈技术知识库</a>。 涵盖赛场离散环境拓扑建模、DFS 9×7 全网格覆盖搜索、Dijkstra 动态绕障重规划算法以及飞行任务有限状态机（FSM）调度架构。</p></blockquote><hr><h2 id="_1-赛场环境离散拓扑图建模" tabindex="-1">1. 赛场环境离散拓扑图建模 <a class="header-anchor" href="#_1-赛场环境离散拓扑图建模" aria-label="Permalink to &quot;1. 赛场环境离散拓扑图建模&quot;">​</a></h2><p>参考源码：<code>01_锡月无人机实战系统/02_树莓派机载主控/自启动/path_generator.py</code></p><p>在电赛 2025-H 题（野生动物巡查）等赛题中，比赛场地为 <strong>450cm × 350cm</strong> 的矩形区域（由 500cm × 400cm 喷绘布四周各留 25cm 边距形成），划分为 <strong>63 个 50cm × 50cm 方格</strong>。若直接在连续空间规划轨迹，不仅解算复杂度极高，且易因累积误差偏离航线。工程上的标准解法是将连续空间<strong>离散化为网格拓扑图 G(V, E)</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         B7 ┌───┬───┬───┬───┬───┬───┬───┬───┬───┐</span></span>
<span class="line"><span>            │A1B7│A2B7│A3B7│A4B7│A5B7│A6B7│A7B7│A8B7│A9B7│</span></span>
<span class="line"><span>            ├───┼───┼───┼───┼───┼───┼───┼───┼───┤</span></span>
<span class="line"><span>            │...│...│...│...│...│...│...│...│...│   （B6~B2 共 5 行）</span></span>
<span class="line"><span>            ├───┼───┼───┼───┼───┼───┼───┼───┼───┤</span></span>
<span class="line"><span>         B1 │A1B1│A2B1│A3B1│A4B1│A5B1│A6B1│A7B1│A8B1│🔴A9B1│</span></span>
<span class="line"><span>            └───┴───┴───┴───┴───┴───┴───┴───┴───┘</span></span>
<span class="line"><span>              A1  A2  A3  A4  A5  A6  A7  A8  A9  ► X（长 450cm）</span></span>
<span class="line"><span>                                            起飞区（红色圆圈）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_1-1-网格参数与坐标映射-与真题及工程代码一致" tabindex="-1">1.1 网格参数与坐标映射（与真题及工程代码一致） <a class="header-anchor" href="#_1-1-网格参数与坐标映射-与真题及工程代码一致" aria-label="Permalink to &quot;1.1 网格参数与坐标映射（与真题及工程代码一致）&quot;">​</a></h3><ul><li><strong>网格规格</strong>：横向 A1~A9 共 <strong>9 列</strong>（X 轴，长 450cm），纵向 B1~B7 共 <strong>7 行</strong>（Y 轴，宽 350cm），方格以代码 <strong>AnBm</strong>（如 A3B5）命名——与 2025 真题图 1 及 <code>path_generator.py</code> 的解析逻辑完全一致；</li><li><strong>单元格物理尺寸</strong>：相邻方格中心间距 50cm（<code>ΔX = ΔY = 0.5m</code>），四周保留安全缓冲区；</li><li><strong>世界坐标约定（锡月工程）</strong>：以起飞区 <strong>A9B1 为原点</strong>，与代码中 <code>X = (A 序号 − 9) × 0.5m</code>、<code>Y = (B 序号 − 1) × 0.5m</code> 的换算一致（A9 → X=0，B1 → Y=0）；</li><li><strong>禁飞区表达</strong>：真题禁飞区由若干连续方格构成（现场抽签给出方格代码，图 1 示例即 A3B3~A5B3 三个连续方格），规划器将其标记为不可通行节点。</li></ul><hr><h2 id="_2-全覆盖路径规划算法-dfs-蛇形扫描" tabindex="-1">2. 全覆盖路径规划算法（DFS 蛇形扫描） <a class="header-anchor" href="#_2-全覆盖路径规划算法-dfs-蛇形扫描" aria-label="Permalink to &quot;2. 全覆盖路径规划算法（DFS 蛇形扫描）&quot;">​</a></h2><p>为确保巡查过程中不遗漏任何可能出现目标的方格，且总飞行耗时最短，系统采用了改进型<strong>深度优先搜索（DFS）与蛇形往复往返遍历策略</strong>：</p><h3 id="_2-1-规划原则" tabindex="-1">2.1 规划原则 <a class="header-anchor" href="#_2-1-规划原则" aria-label="Permalink to &quot;2.1 规划原则&quot;">​</a></h3><ol><li><strong>转向代价最小化</strong>：四轴无人机在拐弯减速、旋转机头时能量损耗最大；优先沿长轴方向（A1→A9，450cm）做直线连续匀速巡航；</li><li><strong>零回头路</strong>：维护已访问节点位图（Visited Bitmap），除 DFS 回溯外每个有效方格仅途径一次；</li><li><strong>巡航高度恒定</strong>：2025 真题要求巡查高度 <strong>120±10cm</strong> 且全程不得偏离航线，全流程保持定高，待相机检出目标后再执行降高与靶心对准。</li></ol><hr><h2 id="_3-动态避障与重规划算法-dijkstra" tabindex="-1">3. 动态避障与重规划算法（Dijkstra） <a class="header-anchor" href="#_3-动态避障与重规划算法-dijkstra" aria-label="Permalink to &quot;3. 动态避障与重规划算法（Dijkstra）&quot;">​</a></h2><p>在比赛现场，裁判会临时指定若干&quot;禁飞方格代码&quot;（如 <code>A3B3, A4B3, A5B3</code>）。无人机必须具备<strong>毫秒级局部动态绕行重规划能力</strong>（锡月工程实测解算耗时 &lt; 50ms）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[接收地面站下发的禁飞区方格代码]</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ├── 在拓扑图 G(V, E) 中断开与禁飞格连接的全部邻接边 (Weight = ∞)</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>[调用 Dijkstra 算法寻找绕障最短连通拓扑链]</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ├── 剔除共线多余冗余点 (路径平滑与拐点提取)</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>[生成全新 router.txt 航点序列] ──► 注入飞行控制状态机执行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_3-1-核心算法实现细节" tabindex="-1">3.1 核心算法实现细节 <a class="header-anchor" href="#_3-1-核心算法实现细节" aria-label="Permalink to &quot;3.1 核心算法实现细节&quot;">​</a></h3><ul><li><strong>临界无解防护</strong>：若禁飞区将目标或通路完全封死，算法必须提前捕获异常并回退至上一安全悬停点，坚决避免死循环卡死；</li><li><strong>共线航点压缩</strong>：若连续三个路径点 (P1, P2, P3) 斜率相同，直接剔除中间过渡点 P2，将航点序列压至拐弯极值点，保证飞行姿态流畅、不频繁点刹顿挫。</li></ul><h3 id="_3-2-航线文件标准接口规范" tabindex="-1">3.2 航线文件标准接口规范 <a class="header-anchor" href="#_3-2-航线文件标准接口规范" aria-label="Permalink to &quot;3.2 航线文件标准接口规范&quot;">​</a></h3><p>规划算法最终输出标准的 ASCII 航点文件（<code>router.txt</code>），供机载控制核心按行读取（下为锡月工程真实格式示例）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 格式: 目标X(米), 目标Y(米), 目标Z(米), 目标偏航角Yaw(度), 悬停判定时间(秒)</span></span>
<span class="line"><span>0.0, 0.0, 1.5, 0.0, 2.0</span></span>
<span class="line"><span>0.5, 0.0, 1.5, 0.0, 1.0</span></span>
<span class="line"><span>1.0, 0.0, 1.5, 0.0, 1.0</span></span>
<span class="line"><span>1.5, 0.5, 1.5, 90.0, 1.5</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="_4-飞行任务有限状态机-fsm-开发架构" tabindex="-1">4. 飞行任务有限状态机（FSM）开发架构 <a class="header-anchor" href="#_4-飞行任务有限状态机-fsm-开发架构" aria-label="Permalink to &quot;4. 飞行任务有限状态机（FSM）开发架构&quot;">​</a></h2><p>参考源码：<code>01_锡月无人机实战系统/02_树莓派机载主控/自启动/A_fly_deal.py</code></p><p>整个全自主飞行流程绝不采用单线程 <code>while(1) + time.sleep()</code> 的初学者写法，而是构建严格的<strong>事件驱动型有限状态机（Finite State Machine）</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┐     按键触发模式选择 / 地面站起飞帧</span></span>
<span class="line"><span>│  1. IDLE     │ ──────────────────────────────────────► ┌──────────────┐</span></span>
<span class="line"><span>│  待机自检    │                                         │ 2. TAKEOFF   │</span></span>
<span class="line"><span>└──────────────┘                                         │ 垂直起飞定高 │</span></span>
<span class="line"><span>                                                         └──────┬───────┘</span></span>
<span class="line"><span>                                                                │ 达到定高且位姿收敛</span></span>
<span class="line"><span>                                                                ▼</span></span>
<span class="line"><span>┌──────────────┐     检出目标靶心 / 触发降落点          ┌──────────────┐</span></span>
<span class="line"><span>│ 4. DESCEND   │ ◄────────────────────────────────────── │ 3. NAVIGATE  │</span></span>
<span class="line"><span>│ 降高至0.5m对准│                                         │ 航点循迹巡航 │</span></span>
<span class="line"><span>└──────┬───────┘                                         └──────────────┘</span></span>
<span class="line"><span>       │ 水平位置偏差 &lt; 3cm</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌──────────────┐     稳定悬停 1.0 秒</span></span>
<span class="line"><span>│ 5. HOVER_WAIT│ ──────────────────────────────────────► ┌──────────────┐</span></span>
<span class="line"><span>│ 确认目标/拍照│                                         │  6. LAND     │</span></span>
<span class="line"><span>└──────────────┘                                         │ 关油门切电落地│</span></span>
<span class="line"><span>                                                         └──────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h3 id="_4-1-各状态职责与安全转移条件" tabindex="-1">4.1 各状态职责与安全转移条件 <a class="header-anchor" href="#_4-1-各状态职责与安全转移条件" aria-label="Permalink to &quot;4.1 各状态职责与安全转移条件&quot;">​</a></h3><ol><li><strong>IDLE（待机自检）</strong>：检查 T265 追踪置信度、飞控串口连通性与电池电压；双色 LED 红灯闪烁表示自检，绿灯长亮表示就绪；</li><li><strong>TAKEOFF（垂直起飞）</strong>：向飞控发送垂直上升速度指令，利用激光 ToF 实时监测高度；当达到定高窗口（示例工程为 1.5m ± 5cm，赛题按 120±10cm 校验）且水平漂移 &lt; 3cm 持续 1 秒，无缝切入 <code>NAVIGATE</code>；</li><li><strong>NAVIGATE（航点循迹）</strong>：按行迭代 <code>router.txt</code> 中的航点；以当前实际坐标与目标坐标计算三维误差向量，并传入位置环控制器；若视觉线程检出同心圆或识别目标，立刻挂起巡航切入 <code>DESCEND</code>；</li><li><strong>DESCEND（阶梯降高）</strong>：一阶下降至安全观测高度（如 0.5m），开启单目反投影闭环对准，消除下视对准误差；</li><li><strong>HOVER_WAIT（悬停确认）</strong>：在对准后的目标正上方保持零速度稳态悬停，触发声光报警/投放机构，并通过蓝牙回传播报；</li><li><strong>LAND（断电接地）</strong>：发送负垂直速度平稳接地；ToF 测得高度 &lt; 10cm 且持续下降率归零时，发送飞控加锁（Disarm）指令，彻底切断电机 PWM 输出。</li></ol>`,30)])])}const u=n(l,[["render",r]]);export{m as __pageData,u as default};
